    for (auto& x : a) cin >> x;
    for (auto& x : r) cin >> x;
    vector<long long> cum(t, 0);
    long long prev = 0;
    for (int j = 0; j + 1 < t; j++) {
        cum[j + 1] = cum[j] + r[j] * (a[j] - prev);
        prev = a[j];
    }
    int q;
    cin >> q;
    while (q--) {
        long long v;
        cin >> v;
        int j = lower_bound(a.begin(), a.end(), v) - a.begin();
        long long lo = j > 0 ? a[j - 1] : 0;
